local AL=(getgenv and getgenv()) or _ENV or _G
local oj={} for i=97,122 do oj[#oj+1]=string.char(i) end
local uJ={12,15,1,4,19,20,18,9,14,7}
local ov="" for i=1,#uJ do ov=ov..oj[uJ[i]] end
local aF=AL and AL[ov]
local yp=type(aF)=="function"
if yp then
local ut={8,15,15,11,6,21,14,3,20,9,15,14}
local aV="" for i=1,#ut do aV=aV..oj[ut[i]] end
local sr={18,5,19,20,15,18,5,6,21,14,3,20,9,15,14}
local MX="" for i=1,#sr do MX=MX..oj[sr[i]] end
local Ir=AL[aV]
local SN=AL[MX]
local Yf=false
if type(Ir)=="function" and type(SN)=="function" then
local EX=function() return 5 end
local OR=pcall(Ir,EX,function() return -777 end)
if OR and EX()==-777 then
local wn=pcall(SN,EX)
Yf=(wn and EX()==5)
end
if not Yf then pcall(SN,EX) end
if not Yf and type(AL.math)=="table" and type(AL.math.abs)=="function" then
local KZ=AL.math.abs
if KZ(5)==5 then
local ap,it=pcall(Ir,KZ,function() return -777 end)
if ap and KZ(5)==-777 then
local sz=pcall(SN,KZ)
Yf=(sz and KZ(5)==5)
if not Yf then pcall(SN,KZ) AL.math.abs=(type(it)=="function" and it) or function(v) if v<0 then return -v end return v end end
end
end
end
if Yf then
local gn={aF,Ir,SN}
local md=AL.string
if type(md)=="table" then
gn[#gn+1]=md.char gn[#gn+1]=md.byte gn[#gn+1]=md.sub gn[#gn+1]=md.rep gn[#gn+1]=md.len
end
if type(AL.table)=="table" and AL.table.concat then gn[#gn+1]=AL.table.concat end
if AL.pcall then gn[#gn+1]=AL.pcall end
if type(AL.math)=="table" and AL.math.floor then gn[#gn+1]=AL.math.floor end
for Cl=1,#gn do local zt=gn[Cl] if type(zt)=="function" then pcall(SN,zt) end end
end
end
end
if not yp then return nil end

